import { useEffect, useState } from "react";
import ProgressBar from "../components/ProgressBar";
import ProgressChart from "../components/ProgressChart";

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({});
  const [streak, setStreak] = useState(0);
  const [xp, setXP] = useState(0);
  const [level, setLevel] = useState(1);
  const [badges, setBadges] = useState([]);
  const [completedDays, setCompletedDays] = useState([]);
  const [recommendation, setRecommendation] = useState("");

  useEffect(() => {
    // 📊 DATA
    const quizScore = parseInt(localStorage.getItem("quizScore") || "0");
    const totalQuestions = parseInt(localStorage.getItem("totalQuestions") || "1");

    const completed = parseInt(localStorage.getItem("lastCompletedCount") || "0");
    const totalTasks = parseInt(localStorage.getItem("lastTotalTasks") || "1");

    const completedDaysData = JSON.parse(localStorage.getItem("completedDays") || "[]");
    const frozenDays = JSON.parse(localStorage.getItem("frozenDays") || "[]");

    const currentDay = parseInt(localStorage.getItem("currentDay") || "1");

    // 📈 METRICS
    const quiz = Math.round((quizScore / totalQuestions) * 100);
    const tasks = Math.round((completed / totalTasks) * 100);
    const consistency = Math.round(
      (completedDaysData.length / currentDay) * 100
    );

    // 🔥 STREAK (WITH FREEZE)
    let currentStreak = 0;

    for (let i = currentDay - 1; i >= 0; i--) {
      if (
        completedDaysData.includes(i) ||
        frozenDays.includes(i)
      ) {
        currentStreak++;
      } else {
        break;
      }
    }

    // 🎮 XP + LEVEL
    const totalXP = parseInt(localStorage.getItem("xp") || "0");
    const calculatedLevel = Math.floor(totalXP / 100) + 1;

    // 🤖 RECOMMENDATION
    const generateRecommendation = () => {
      if (tasks < 50) return "⚡ Focus on completing daily tasks consistently.";
      if (quiz < 60) return "🧠 Revise fundamentals and reattempt quizzes.";
      if (consistency < 70) return "📅 Maintain daily streak.";
      if (tasks > 80 && quiz > 80)
        return "🚀 You're ahead! Start building projects.";
      return "👍 You're doing well. Keep improving.";
    };

    // 🏅 BADGES
    const getBadges = () => {
      const b = [];
      if (currentStreak >= 3) b.push("🔥 3 Day Streak");
      if (currentStreak >= 7) b.push("🚀 7 Day Warrior");
      if (quiz >= 80) b.push("🧠 Quiz Master");
      if (consistency >= 70) b.push("📅 Consistency King");
      if (totalXP >= 500) b.push("🏆 Level Grinder");
      return b;
    };

    // SET STATE
    setMetrics({ quiz, tasks, consistency });
    setStreak(currentStreak);
    setXP(totalXP);
    setLevel(calculatedLevel);
    setBadges(getBadges());
    setCompletedDays(completedDaysData);
    setRecommendation(generateRecommendation());
  }, []);

  return (
    <div className="space-y-8">

      {/* HEADER */}
      <div className="rounded-[2rem] bg-slate-800 border border-slate-700 p-6 shadow-xl">
        <h2 className="text-2xl font-bold text-white">📊 Progress Dashboard</h2>
        <p className="text-slate-400 mt-2">
          Track your growth and stay consistent 🚀
        </p>
      </div>

      {/* XP + LEVEL */}
      <div className="grid gap-6 md:grid-cols-2">
        <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
          <p className="text-slate-400">Total XP</p>
          <h3 className="text-3xl text-white font-bold mt-2">{xp}</h3>
        </div>

        <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
          <p className="text-slate-400">Level</p>
          <h3 className="text-3xl text-white font-bold mt-2">
            Level {level}
          </h3>
        </div>
      </div>

      {/* GRAPH */}
      <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
        <h3 className="text-white font-semibold mb-4">📈 Weekly Progress</h3>
        <ProgressChart />
      </div>

      {/* METRICS */}
      <div className="grid gap-6 md:grid-cols-3">
        {[
          { label: "Consistency", value: metrics.consistency },
          { label: "Quiz", value: metrics.quiz },
          { label: "Tasks", value: metrics.tasks },
        ].map((item) => (
          <div
            key={item.label}
            className="bg-slate-800 border border-slate-700 p-6 rounded-2xl"
          >
            <p className="text-slate-400">{item.label}</p>
            <ProgressBar value={item.value} />
          </div>
        ))}
      </div>

      {/* STREAK */}
      <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
        <h3 className="text-white">🔥 Streak</h3>
        <p className="text-3xl text-white font-bold mt-2">
          {streak} days
        </p>
      </div>

      {/* RECOMMENDATION */}
      <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
        <h3 className="text-white">🤖 Smart Recommendation</h3>
        <p className="text-slate-300 mt-2">{recommendation}</p>
      </div>

      {/* BADGES */}
      <div className="bg-slate-800 border border-slate-700 p-6 rounded-2xl">
        <h3 className="text-white">🏅 Achievements</h3>

        <div className="mt-4 flex flex-wrap gap-3">
          {badges.length > 0 ? (
            badges.map((b, i) => (
              <span
                key={i}
                className="px-4 py-2 bg-gradient-to-r from-blue-500 to-purple-500 text-white rounded-full text-sm"
              >
                {b}
              </span>
            ))
          ) : (
            <p className="text-slate-400">No badges yet</p>
          )}
        </div>
      </div>

    </div>
  );
}
